function Usuario() {
  const [usuario, setUsuario] = useState({ nombre: "Ana", edad: 30 });

  function cumpleAnios() {
    setUsuario({ edad: usuario.edad + 1 });
  }

  return <button onClick={cumpleAnios}>{usuario.nombre}</button>;
}

